import itertools

# Represent vectors as integers 0..31 (5 bits)
def subspace_from_basis(a, b):
    """Generate 2D subspace {0, a, b, a^b}"""
    return frozenset({0, a, b, a ^ b})

def is_subspace(s):
    # check if s is a 2D subspace containing 0
    if len(s) != 4 or 0 not in s:
        return False
    elems = list(s)
    a = elems[1]
    b = elems[2]
    return (a ^ b) in s

# Generate all 2D subspaces
subspaces = set()
for a in range(1, 32):
    for b in range(a+1, 32):
        s = subspace_from_basis(a, b)
        # ensure canonical representation: sort non-zero elements
        # but frozenset is fine
        subspaces.add(s)

subspaces = list(subspaces)
print(f"Total 2D subspaces: {len(subspaces)}")

# Check intersection property
def intersect_trivially(s1, s2):
    return len(s1.intersection(s2)) == 1  # only 0

# Greedy search for 6 subspaces with pairwise trivial intersection
found = None

# Try simple greedy
for start in subspaces:
    selected = [start]
    for s in subspaces:
        if s in selected:
            continue
        if all(intersect_trivially(s, t) for t in selected):
            selected.append(s)
            if len(selected) == 6:
                found = selected
                break
    if found:
        break

if found:
    print("Found 6 subspaces:")
    for i, s in enumerate(found):
        print(f"U{i} = {sorted(s)}")
else:
    print("Greedy failed, trying backtracking...")
    # Backtracking
    def backtrack(selected, idx):
        if len(selected) == 6:
            return selected[:]
        if idx >= len(subspaces):
            return None
        # Option 1: skip
        res = backtrack(selected, idx+1)
        if res:
            return res
        # Option 2: take if compatible
        s = subspaces[idx]
        if all(intersect_trivially(s, t) for t in selected):
            selected.append(s)
            res = backtrack(selected, idx+1)
            selected.pop()
            if res:
                return res
        return None

    found = backtrack([], 0)
    if found:
        print("Found 6 subspaces via backtracking:")
        for i, s in enumerate(found):
            print(f"U{i} = {sorted(s)}")
    else:
        print("No set of 6 subspaces found?")

